def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Implements the patience sorting algorithm in O(n log n) time.
    """
    import bisect
    tails = []  # tails[i] holds the smallest possible tail of an increasing subsequence of length i+1
    for x in nums:
        # Find the leftmost index to replace (first >= x)
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

