code:
def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting O(n log n).
    """
    import bisect
    tails = []  # tails[i] = minimal possible tail of an inc subseq of length i+1
    for x in nums:
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

